sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // Prevent script execution on form load or when source field is cleared
    if (isLoading || !newValue) {
        return;
    }

    // Map source field values to target field values
    switch (newValue) {
        case 'NVPV':
            g_form.setValue('code', newValue);
            //g_form.setValue('fine_amount', '30.00');
            break;

        case 'SPEED':
            g_form.setValue('code', newValue);
            //g_form.setValue('fine_amount', '25.00');
            break;

        case 'OT':
        case 'SSV':
        case 'IP':
        case 'PFL':
        case 'OV':
            g_form.setValue('code', newValue);
            //g_form.setValue('fine_amount', '15.00');
            break;

        case 'RD':
            g_form.setValue('code', newValue);
            //g_form.setValue('fine_amount', '50.00');
            break;

        case 'DP/ADA':
            g_form.setValue('code', newValue);
            //g_form.setValue('fine_amount', '250.00');
            break;

        case 'RPDP':
            g_form.setValue('code', newValue);
            //g_form.setValue('fine_amount', '450.00');
            break;
    }
}
